import type { PageLang } from '@/lib/localized-routes';
const translations: Record<'es'|'pt',Record<string,string>> = {
  "es": {
    "Start and Transfer Readiness": "Disponibilidad de arranque y transferencia",
    "A standby generator may have to start and accept facility load after long idle periods. Battery, controls and automatic transfer switch condition must be checked separately from engine filtration.": "Un generador de reserva puede tener que arrancar y asumir la carga tras largos períodos de inactividad. El estado de baterías, controles y transferencia automática debe verificarse por separado de la filtración del motor.",
    "Load Testing and Low-Load Duty": "Pruebas bajo carga y operación a baja carga",
    "Standby sets exercised with little or no load may develop wet stacking in some diesel engines. Use the manufacturer-approved testing and loading procedure; filtration does not correct low-load operating conditions.": "En algunos motores diésel, las pruebas reiteradas con carga baja o nula pueden producir acumulación de combustible y residuos en el escape (wet stacking). Aplique el procedimiento de pruebas y carga aprobado por el fabricante; la filtración no corrige esas condiciones de operación.",
    "Cooling-fluid condition and unobstructed heat rejection matter under load. A coolant filter is appropriate only where specified by the generator-engine OEM.": "El estado del refrigerante y la disipación térmica sin obstrucciones son importantes bajo carga. Un filtro de refrigerante solo corresponde cuando está especificado por el fabricante del motor.",
    "Filtration manages defined engine contamination risks. Electrical availability also depends on batteries, controls, alternator, protection, switching and verified testing.": "La filtración controla riesgos definidos de contaminación del motor. La disponibilidad eléctrica también depende de baterías, controles, alternador, protecciones, conmutación y pruebas verificadas.",
    "Diesel-fuel particulate control, approved fuel/water separation, engine air intake and lubrication are frequent filtration priorities. Cooling-system filtration applies only where an OEM-approved filter circuit exists. Selection depends on the engine, duty, stored-fuel conditions and verified application.": "El control de partículas del diésel, la separación aprobada de agua, la admisión de aire y la lubricación suelen ser prioridades de filtración. La filtración de refrigerante aplica solo si existe un circuito aprobado por el fabricante. La selección depende del motor, su régimen, el combustible almacenado y la aplicación verificada.",
    "Generator engines can transition quickly to substantial thermal load. Coolant quality, radiator airflow, heat exchanger condition and OEM maintenance requirements matter. A coolant filter must not be assumed compatible unless a specified circuit and application exist.": "Los motores de los generadores pueden pasar rápidamente a una carga térmica elevada. Importan la calidad del refrigerante, el flujo de aire del radiador, el intercambiador de calor y los requisitos de mantenimiento OEM. No debe presumirse compatible un filtro de refrigerante sin circuito y aplicación especificados.",
    "A known OEM or filter reference is a starting point for searching candidate cross-references in Part Search. Final compatibility must be verified against generator or engine identity, dimensions, protected system and documented application evidence; an unverified cross-reference is not an approved fitment.": "Una referencia OEM o de filtro permite buscar equivalencias candidatas en Part Search. La compatibilidad final requiere verificar la identidad del generador o motor, dimensiones, sistema protegido y evidencia documentada; una equivalencia no verificada no constituye una aplicación aprobada.",
    "Does replacing the filter prove that a standby generator will start and transfer the load?": "¿Cambiar el filtro demuestra que el generador de reserva arrancará y transferirá la carga?",
    "No. Filtration controls specific contamination risks in engine systems. Emergency readiness also requires OEM-directed starting-system, battery, charging, controls, ATS, protection and appropriate load-testing checks performed by qualified personnel.": "No. La filtración controla riesgos específicos de contaminación de los sistemas del motor. La disponibilidad para emergencias exige además verificaciones de arranque, baterías, carga, controles, ATS, protecciones y pruebas bajo carga según el fabricante y por personal calificado.",
    "Disable unintended automatic starting and follow the OEM isolation procedure before servicing. Verify filter and seal, prevent contamination and document leak checks, safe recommissioning and restoration of the specified standby mode.": "Desactive el arranque automático involuntario y aplique el procedimiento de aislamiento OEM antes de intervenir. Verifique filtro y sello, evite contaminación y documente fugas, puesta en servicio segura y restitución al modo de reserva especificado.",
    "Scope: filtration reduces specified contamination risks but cannot verify generator start, load acceptance or automatic transfer. Battery, controls, ATS, alternator, electrical protection and OEM-approved load tests require separate checks. Coolant filters require a specified compatible circuit and coolant chemistry.": "Alcance: la filtración reduce riesgos determinados de contaminación, pero no verifica el arranque, la aceptación de carga ni la transferencia automática. Baterías, controles, ATS, alternador, protecciones eléctricas y pruebas bajo carga aprobadas por el OEM requieren controles independientes. Los filtros de refrigerante exigen un circuito compatible y química del fluido especificados.",
    "POWER GENERATION / ASSET READINESS": "GENERACIÓN ELÉCTRICA / DISPONIBILIDAD DE ACTIVOS",
    "FILTRATION FOR": "FILTRACIÓN PARA",
    "POWER GENERATION EQUIPMENT": "EQUIPOS DE GENERACIÓN ELÉCTRICA",
    "Engineering support for generator owners, facility maintenance managers, reliability engineers and service technicians.": "Ingeniería de filtración para propietarios de generadores, responsables de mantenimiento, ingenieros de confiabilidad y técnicos de servicio.",
    "Keep standby and prime-power diesel engines prepared for demand. Manage stored-fuel water and particles, air-intake restriction, lubricating-oil condition and OEM-specified coolant filtration before the next load event.": "Mantenga los motores diésel de grupos electrógenos de reserva y potencia principal preparados para entrar en carga. Controle el agua y las partículas del combustible almacenado, la restricción de admisión, el estado del aceite y la filtración de refrigerante especificada por el fabricante.",
    "PLAN GENERATOR MAINTENANCE": "PLANIFICAR MANTENIMIENTO DEL GENERADOR",
    "Scope: filtration does not replace battery, starting system, switchgear, automatic transfer switch or electrical load-testing inspections. Cooling-system filters must be specified for the engine and coolant chemistry.": "Alcance: la filtración no sustituye las inspecciones de baterías, arranque, interruptores, transferencia automática ni las pruebas eléctricas bajo carga. Los filtros de refrigeración deben estar especificados para el motor y la composición química del refrigerante.",
    "Power generation equipment applications": "Aplicaciones de equipos de generación eléctrica",
    "Industrial generator set for standby and prime power applications": "Grupo electrógeno industrial para servicio de reserva y potencia principal",
    "SERVICE CHECK": "CONTROL DE MANTENIMIENTO",
    "GENERATOR MAINTENANCE RESPONSIBILITIES": "RESPONSABILIDADES EN EL MANTENIMIENTO DE GENERADORES",
    "Four decisions that keep a generator ready for demand.": "Cuatro decisiones para mantener el generador preparado para entrar en servicio.",
    "A ready generator requires coordinated maintenance, not just a replacement filter. Separate contamination and engine issues from starting, transfer-switch and electrical failures; use the equipment manufacturer's complete readiness procedure.": "Un generador disponible exige mantenimiento coordinado, no solo cambiar un filtro. Distinga problemas de contaminación y motor de fallas de arranque, transferencia y sistemas eléctricos; aplique el procedimiento completo del fabricante.",
    "Send generator-set and engine model, standby or prime duty, operating and idle hours, fuel-storage history, current filter references, restriction or fluid observations, test results, maintenance log and next service window.": "Indique modelo del grupo electrógeno y motor, régimen de reserva o potencia principal, horas de operación e inactividad, historial de combustible almacenado, referencias de filtros, observaciones de restricción o fluidos, resultados de pruebas, historial y próxima ventana de mantenimiento.",
    "Tank breathing, condensation and water in stored diesel fuel": "Respiración del tanque, condensación y agua en el diésel almacenado",
    "FUEL PARTICULATE": "PARTÍCULAS EN EL COMBUSTIBLE",
    "Dirt introduced into diesel tanks, transfer hoses and filling points": "Suciedad introducida en tanques de diésel, mangueras de trasvase y puntos de llenado",
    "DIESEL FUEL": "COMBUSTIBLE DIÉSEL",
    "Scale, corrosion debris and coolant condition where a filtration circuit is specified": "Incrustaciones, residuos de corrosión y estado del refrigerante cuando se especifique un circuito de filtración",
    "Generator owner": "Propietario del generador",
    "Define the cost of lost power, critical loads and spare-part coverage. Confirm who can authorize maintenance and what emergency service is available.": "Determine el costo de perder energía, las cargas críticas y la disponibilidad de repuestos. Confirme quién autoriza el mantenimiento y qué servicio de emergencia está disponible.",
    "Facility maintenance manager": "Responsable de mantenimiento de instalaciones",
    "Plan calendar-based inspections, fuel storage and water checks, safe service access, documented test schedules and corrective work before the next power event.": "Planifique inspecciones por calendario, controles del combustible almacenado y del agua, acceso seguro, pruebas documentadas y trabajos correctivos antes de la próxima interrupción eléctrica.",
    "Reliability engineer": "Ingeniero de confiabilidad",
    "Review stored-fuel condition, engine alerts, measured restriction where instrumented, load-test results and OEM application evidence; separate engine filtration from controls and electrical faults.": "Revise el combustible almacenado, alarmas del motor, restricción medida cuando exista instrumentación, resultados de pruebas bajo carga y evidencia OEM; diferencie la filtración del motor de fallas eléctricas y de control.",
    "Service technician": "Técnico de mantenimiento",
    "Apply lockout and manufacturer isolation procedures, verify the filter and seal, prevent contamination during replacement and document leak checks and return-to-ready testing.": "Aplique los procedimientos de bloqueo y aislamiento del fabricante, verifique filtro y sello, evite introducir contaminación durante el cambio y documente fugas y pruebas de retorno a disponibilidad.",
    "Inspect water accumulation and drain points in stored-diesel systems; use the specified conventional fuel/water separator configuration, not a turbine substitute.": "Inspeccione acumulación de agua y drenajes en sistemas de diésel almacenado; utilice el separador convencional de combustible/agua especificado, no un sustituto tipo turbina.",
    "Review diesel particulate exposure during transfers and fueling; check engine-specific filtration and restriction requirements.": "Revise el ingreso de partículas en el diésel durante trasvases y abastecimiento; compruebe los requisitos de filtración y restricción propios del motor.",
    "Check intake restriction, filter-housing sealing and air paths; follow the engine OEM service criteria.": "Compruebe restricción de admisión, sellos de la carcasa y conductos de aire; siga los criterios de mantenimiento OEM del motor.",
    "Review oil condition, service history and operating hours against the engine manufacturer requirements.": "Revise estado del aceite, historial de mantenimiento y horas de operación conforme a los requisitos del fabricante del motor.",
    "Only evaluate a coolant filter when the engine manufacturer specifies a compatible cooling-system filtration circuit; verify coolant chemistry and service requirements.": "Considere un filtro de refrigerante solo cuando el fabricante del motor especifique un circuito compatible de filtración; verifique química del refrigerante y requisitos de servicio.",
    "POWER GENERATION / READINESS PROTECTION": "GENERACIÓN ELÉCTRICA / PROTECCIÓN DE DISPONIBILIDAD",
    "Power Generation Filtration": "Filtración para generación eléctrica",
    "Systems": "Sistemas",
    "Protect the generator before the facility has to depend on it.": "Proteja el generador antes de que la instalación tenga que depender de él.",
    "Fuel, air, lubrication and cooling-system contamination control for standby generators, prime-power systems and industrial engine-driven generation equipment operating across stored readiness, testing and sustained load.": "Control de contaminación de combustible, aire, lubricación y refrigeración para generadores de reserva, generación principal y equipos industriales desde la preparación y las pruebas hasta la carga sostenida.",
    "IDENTIFY MY GENERATOR PROTECTION PATH": "IDENTIFICAR LA PROTECCIÓN DE MI GENERADOR",
    "FIND MY FILTER": "ENCONTRAR MI FILTRO",
    "DIRECT ANSWER": "RESPUESTA DIRECTA",
    "What defines the correct power-generation filtration strategy?": "¿Qué define la estrategia correcta de filtración para generación eléctrica?",
    "Power-generation filtration starts with the generator set and its readiness requirement, then resolves stored-fuel condition, protected system, standby or prime-power duty, environmental exposure, maintenance access and validated application evidence. A filter should not be selected from running hours or generator category alone.": "La selección comienza por el grupo electrógeno y sus requisitos de disponibilidad; después considera combustible almacenado, sistema protegido, servicio de emergencia o principal, entorno, mantenimiento y evidencia validada. No basta con las horas de uso o la categoría del generador.",
    "READINESS BEFORE RUNTIME": "DISPONIBILIDAD ANTES DE LA OPERACIÓN",
    "A standby generator can develop risk while it is not running.": "Un generador de reserva puede acumular riesgos incluso apagado.",
    "Power-generation protection is unusual because the critical event may happen after long periods of low utilization. Stored fluids, environmental exposure and maintenance condition continue to matter while the hour meter barely moves.": "La protección es particular porque el evento crítico puede llegar tras largos períodos de uso escaso. Los fluidos almacenados, el ambiente y el mantenimiento importan incluso cuando el horómetro apenas avanza.",
    "Different power roles. Different readiness demands.": "Funciones eléctricas distintas. Exigencias de disponibilidad diferentes.",
    "A hospital standby set, a remote prime-power unit and an industrial emergency generator may share similar engines while operating under very different fuel-storage, testing, loading and maintenance conditions.": "Un generador hospitalario de reserva, una unidad principal remota y un grupo de emergencia industrial pueden compartir motores, pero diferir en almacenamiento de combustible, pruebas, carga y mantenimiento.",
    "READINESS PATHWAYS": "RUTAS DE DISPONIBILIDAD",
    "Connect the failure source to the system that must respond on demand.": "Vincule la fuente de falla con el sistema que debe responder cuando se necesite.",
    "Selection should move from contamination source to protected system, then to the appropriate ELIMFILTERS technology and finally to a validated part.": "La selección debe partir de la fuente de contaminación, pasar por el sistema protegido y la tecnología ELIMFILTERS y finalizar con una pieza validada.",
    "CONTAMINATION SOURCE": "FUENTE DE CONTAMINACIÓN",
    "PROTECTION SYSTEM": "SISTEMA DE PROTECCIÓN",
    "ELIMFILTERS TECHNOLOGY": "TECNOLOGÍA ELIMFILTERS",
    "EXPLORE →": "EXPLORAR →",
    "POWER GENERATION ENGINEERING PRINCIPLE": "PRINCIPIO DE INGENIERÍA DE GENERACIÓN",
    "A generator filter decision must resolve readiness duty, stored-fluid condition, protected system, environmental exposure and application evidence before the product number is accepted.": "La selección de filtros debe confirmar el régimen de disponibilidad, estado de fluidos almacenados, sistema protegido, entorno y evidencia de aplicación antes de aceptar una referencia.",
    "POWER AVAILABILITY": "DISPONIBILIDAD ELÉCTRICA",
    "The filtration consequence is measured when the generator is called.": "La consecuencia de la filtración se mide cuando se necesita el generador.",
    "For standby and emergency systems, the relevant question is not only whether the engine can run. It is whether the complete generating asset is ready to start, stabilize and carry the required duty when the site loses normal power.": "En sistemas de reserva y emergencia no basta con que el motor funcione. Todo el conjunto debe poder arrancar, estabilizarse y asumir la carga necesaria cuando falla la red.",
    "FROM READINESS CONDITION TO PART": "DE LA DISPONIBILIDAD A LA PIEZA",
    "Resolve the generator application in five decisions.": "Defina la aplicación del generador en cinco decisiones.",
    "APPLICATION EVIDENCE": "EVIDENCIA DE APLICACIÓN",
    "A generator cross-reference still has to match the actual set and duty.": "Una equivalencia debe coincidir con el grupo electrógeno y su servicio real.",
    "Final identification should reconcile the known reference, generator-set or engine context, dimensions, protected system and operating responsibility. Where evidence is incomplete, the application should remain under review rather than be treated as confirmed.": "La identificación final debe conciliar la referencia, el grupo o motor, las dimensiones, el sistema protegido y su función operativa. Si la evidencia es incompleta, la aplicación sigue en revisión.",
    "POWER GENERATION FILTRATION QUESTIONS": "PREGUNTAS DE FILTRACIÓN PARA GENERACIÓN ELÉCTRICA",
    "What facility, reliability and maintenance teams need to know.": "Lo que deben saber los equipos de instalaciones, confiabilidad y mantenimiento.",
    "HAVE A GENERATOR OR READINESS PROBLEM?": "¿TIENE UN PROBLEMA DE GENERADOR O DISPONIBILIDAD?",
    "Identify the protection path before the next outage tests the asset.": "Determine la protección antes de que el próximo corte ponga a prueba el equipo.",
    "Send the generator set or engine, protected system, standby or prime-power duty, fuel-storage conditions and any known OEM or filter reference.": "Indique generador o motor, sistema protegido, tipo de servicio, almacenamiento del combustible y referencias OEM o de filtro conocidas.",
    "ALREADY HAVE A PART NUMBER?": "¿YA TIENE UN NÚMERO DE PIEZA?",
    "Go directly to Part Search.": "Vaya directamente al buscador de filtros.",
    "SERVE POWER-GENERATION CUSTOMERS?": "¿ATIENDE CLIENTES DE GENERACIÓN ELÉCTRICA?",
    "Evaluate distributor fit.": "Evalúe su perfil de distribuidor.",
    "BECOME A DISTRIBUTOR": "SER DISTRIBUIDOR",
    "Standby Generator Sets": "Grupos electrógenos de reserva",
    "Prime Power Systems": "Sistemas de generación principal",
    "Emergency Power Systems": "Sistemas de energía de emergencia",
    "Industrial Diesel Generators": "Generadores diésel industriales",
    "Remote Power Units": "Unidades eléctricas remotas",
    "Engine-Driven Generation Equipment": "Equipos de generación accionados por motor",
    "Stored Fuel": "Combustible almacenado",
    "Start Readiness": "Preparación para arranque",
    "Thermal Control": "Control térmico",
    "Duty Transition": "Transición de servicio",
    "Standby assets may sit for long periods while fuel is exposed to storage time, tank breathing, condensation and transfer contamination.": "Los equipos de reserva pueden pasar largo tiempo detenidos mientras el combustible queda expuesto al almacenamiento, respiración de tanques, condensación y trasvases.",
    "A generator can spend most of its life waiting, then be required to accept load immediately when utility power is unavailable.": "Un generador puede permanecer inactivo gran parte de su vida y necesitar asumir carga inmediatamente cuando falla el suministro público.",
    "Cooling-system condition becomes critical once the engine moves from standby to sustained load and heat rejection increases rapidly.": "La condición del sistema de refrigeración es crítica cuando el motor pasa de reserva a carga sostenida y aumenta rápidamente el calor a disipar.",
    "Prime-power and emergency sets can move between low utilization, testing and extended operation, changing filtration demand across the same asset.": "Los grupos principales y de emergencia pueden alternar entre uso bajo, pruebas y operación prolongada, cambiando las exigencias de filtración.",
    "FUEL + WATER": "COMBUSTIBLE Y AGUA",
    "Stored fuel + tank breathing + condensation + transfer": "Combustible almacenado, respiración de tanques, condensación y trasvase",
    "FUEL / WATER SEPARATION": "SEPARACIÓN DE COMBUSTIBLE Y AGUA",
    "AIRBORNE PARTICULATE": "PARTÍCULAS EN SUSPENSIÓN",
    "Ambient dust + enclosure ingress + engine air demand": "Polvo ambiental, entrada a la carcasa y demanda de aire del motor",
    "AIR INTAKE": "ADMISIÓN DE AIRE",
    "LUBE CONTAMINATION": "CONTAMINACIÓN DEL LUBRICANTE",
    "Wear debris + soot + oxidation byproducts + service ingress": "Residuos de desgaste, hollín, oxidación y entrada durante servicio",
    "LUBRICATION": "LUBRICACIÓN",
    "COOLANT CONTAMINATION": "CONTAMINACIÓN DEL REFRIGERANTE",
    "Scale + corrosion debris + fluid degradation + service contamination": "Incrustaciones, corrosión, degradación del fluido y contaminación durante servicio",
    "COOLING SYSTEM": "SISTEMA DE REFRIGERACIÓN",
    "Starting Reliability": "Confiabilidad de arranque",
    "Fuel, air and lubrication condition influence whether the engine can transition from standby to stable operation when demanded.": "El estado de combustible, aire y lubricación influye en la transición del motor desde reserva a operación estable cuando se necesita.",
    "Load Acceptance": "Aceptación de carga",
    "A generator must move from start-up into electrical load without contamination-related restrictions compromising protected engine systems.": "El generador debe pasar del arranque a la carga eléctrica sin restricciones por contaminación que comprometan sistemas protegidos.",
    "Fuel-System Integrity": "Integridad del sistema de combustible",
    "Stored-fuel contamination can reach pumps and injectors before an emergency event exposes the weakness.": "Los contaminantes del combustible almacenado pueden alcanzar bombas e inyectores antes de que una emergencia revele el problema.",
    "Thermal Stability": "Estabilidad térmica",
    "Cooling-system cleanliness supports controlled heat rejection during sustained generator load.": "La limpieza del sistema de refrigeración favorece una disipación de calor controlada durante carga sostenida.",
    "Maintenance Readiness": "Preparación de mantenimiento",
    "Inspection and service decisions should be completed before an outage turns maintenance access into an operating constraint.": "Las inspecciones y el mantenimiento deben completarse antes de que una interrupción convierta el acceso al servicio en limitación operativa.",
    "Power Availability": "Disponibilidad de energía",
    "The filtration strategy supports the larger requirement: keeping the generating asset ready to deliver power when the facility depends on it.": "La estrategia de filtración responde a la necesidad de mantener el generador preparado para suministrar energía cuando la instalación lo requiera.",
    "Generator / Engine": "Generador / Motor",
    "Readiness Duty": "Régimen de disponibilidad",
    "Stored Condition": "Condición de almacenamiento",
    "Protection": "Protección",
    "Application Evidence": "Evidencia de aplicación",
    "Identify the generator set, engine family and protected subsystem.": "Identifique grupo electrógeno, familia de motor y subsistema protegido.",
    "Define standby, emergency, prime-power or continuous operating responsibility.": "Defina servicio de reserva, emergencia, generación principal u operación continua.",
    "Assess fuel storage, fluid age, environment, testing frequency and contamination exposure.": "Evalúe almacenamiento de combustible, antigüedad de fluidos, entorno, frecuencia de pruebas y exposición a contaminantes.",
    "Match the contamination mechanism to fuel, air intake, lubrication or cooling-system protection.": "Relacione la contaminación con protección de combustible, admisión, lubricación o refrigeración.",
    "Validate the final filter using OEM reference, dimensions and documented application evidence.": "Valide el filtro con referencia OEM, dimensiones y evidencia documentada de aplicación.",
    "What filtration systems are most important on generator sets?": "¿Qué sistemas de filtración son más importantes en grupos electrógenos?",
    "Fuel and water separation, air intake, lubrication and cooling-system protection are common priorities on diesel generator sets. The correct priority depends on whether the unit is standby or prime power, fuel-storage conditions, environment, engine configuration, duty profile and maintenance access.": "Separación de agua del combustible, admisión de aire, lubricación y refrigeración son prioridades en grupos diésel. La importancia relativa depende de si son de reserva o principales, almacenamiento de combustible, entorno, motor, régimen de trabajo y acceso al mantenimiento.",
    "Why is standby generator filtration different from continuously operated equipment?": "¿Por qué la filtración de generadores de reserva es distinta de la de equipos continuos?",
    "A standby generator can remain idle for long periods while fuel, fluids, seals and environmental exposure continue to change. When called, the asset may have to start and accept load immediately. Filtration and maintenance planning should therefore account for stored-fluid condition and readiness, not only running hours.": "El generador de reserva puede permanecer apagado mucho tiempo mientras combustible, fluidos, sellos y exposición ambiental cambian. Cuando se necesita, debe arrancar y asumir carga inmediatamente. Por eso, deben considerarse el estado de fluidos almacenados y la preparación, no solo las horas de uso.",
    "How can stored generator fuel become contaminated?": "¿Cómo puede contaminarse el combustible almacenado para generadores?",
    "Fuel can acquire particulate or water through bulk storage, tank breathing, condensation, transfer equipment, maintenance activity and extended storage. The protection strategy should consider the complete fuel path before fuel reaches sensitive pumps and injectors.": "El combustible puede incorporar partículas y agua durante almacenamiento a granel, respiración de tanques, condensación, trasvase, mantenimiento y permanencia prolongada. La protección debe cubrir toda la ruta hasta bombas e inyectores sensibles.",
    "Why does cooling-system protection matter in power generation?": "¿Por qué importa la protección del sistema de refrigeración en generación?",
    "Generator engines can move rapidly from standby to sustained thermal load. Cooling-system contamination, scale, corrosion debris or degraded fluid condition can interfere with heat transfer and system stability, so coolant protection should be treated as part of asset readiness.": "Los motores pueden pasar rápidamente de reserva a carga térmica sostenida. Contaminantes, incrustaciones, corrosión o refrigerante degradado pueden afectar transferencia de calor y estabilidad; la protección del sistema es parte de la disponibilidad del activo.",
    "Should generator filters be selected only by operating hours?": "¿Deben seleccionarse filtros de generador solo por horas de operación?",
    "No. Running hours do not capture stored-fuel condition, calendar aging, environmental dust, fluid degradation, standby duration, testing frequency or the consequences of an emergency start. Selection and service planning should reflect the actual duty profile.": "No. Las horas no reflejan la calidad del combustible almacenado, envejecimiento, polvo, degradación de fluidos, tiempo en reserva, frecuencia de pruebas o consecuencias del arranque de emergencia. La selección debe reflejar el servicio real.",
    "What information is needed to identify the correct generator filter?": "¿Qué datos se necesitan para identificar el filtro correcto del generador?",
    "Use the generator-set or engine model, protected system, standby or prime-power duty, fuel-storage conditions, environment, OEM or existing part reference, dimensions when available and validated application evidence.": "Utilice modelo del grupo o motor, sistema protegido, régimen de reserva o principal, almacenamiento de combustible, entorno, referencia OEM o pieza actual, dimensiones y evidencia validada.",
    "Can ELIMFILTERS identify a generator filter from an OEM or part number?": "¿Puede ELIMFILTERS identificar un filtro de generador por referencia OEM?",
    "Yes. If an OEM reference or current filter number is known, Part Search provides the fastest route to cross-reference and application information. For an engineering review, include the generator set, engine, protected system and operating duty.": "Sí. Con referencia OEM o número de filtro, Part Search permite consultar equivalencias y aplicaciones. Para una revisión de ingeniería, incluya grupo electrógeno, motor, sistema protegido y régimen operativo."
  },
  "pt": {
    "Start and Transfer Readiness": "Prontidão de partida e transferência",
    "A standby generator may have to start and accept facility load after long idle periods. Battery, controls and automatic transfer switch condition must be checked separately from engine filtration.": "Um gerador de reserva pode precisar partir e assumir carga após longos períodos de inatividade. O estado das baterias, dos controles e da transferência automática deve ser verificado separadamente da filtração do motor.",
    "Load Testing and Low-Load Duty": "Testes sob carga e operação com baixa carga",
    "Standby sets exercised with little or no load may develop wet stacking in some diesel engines. Use the manufacturer-approved testing and loading procedure; filtration does not correct low-load operating conditions.": "Em alguns motores diesel, testes repetidos com carga baixa ou nula podem causar acúmulo de combustível e resíduos no escapamento (wet stacking). Siga os procedimentos de teste e carga aprovados pelo fabricante; a filtração não corrige essas condições de operação.",
    "Cooling-fluid condition and unobstructed heat rejection matter under load. A coolant filter is appropriate only where specified by the generator-engine OEM.": "A condição do líquido de arrefecimento e a dissipação térmica sem obstruções são importantes sob carga. Um filtro do líquido de arrefecimento somente é apropriado quando especificado pelo fabricante do motor.",
    "Filtration manages defined engine contamination risks. Electrical availability also depends on batteries, controls, alternator, protection, switching and verified testing.": "A filtração controla riscos definidos de contaminação do motor. A disponibilidade elétrica também depende de baterias, controles, alternador, proteção, comutação e testes verificados.",
    "Diesel-fuel particulate control, approved fuel/water separation, engine air intake and lubrication are frequent filtration priorities. Cooling-system filtration applies only where an OEM-approved filter circuit exists. Selection depends on the engine, duty, stored-fuel conditions and verified application.": "O controle de partículas no diesel, a separação aprovada de água, a admissão de ar e a lubrificação costumam ser prioridades de filtração. A filtração do líquido de arrefecimento aplica-se apenas quando existe circuito aprovado pelo fabricante. A seleção depende do motor, seu regime, do combustível armazenado e da aplicação verificada.",
    "Generator engines can transition quickly to substantial thermal load. Coolant quality, radiator airflow, heat exchanger condition and OEM maintenance requirements matter. A coolant filter must not be assumed compatible unless a specified circuit and application exist.": "Motores de geradores podem passar rapidamente a uma carga térmica elevada. Importam a qualidade do fluido de arrefecimento, o fluxo de ar no radiador, o trocador de calor e os requisitos OEM. Não presuma compatibilidade de um filtro sem circuito e aplicação especificados.",
    "A known OEM or filter reference is a starting point for searching candidate cross-references in Part Search. Final compatibility must be verified against generator or engine identity, dimensions, protected system and documented application evidence; an unverified cross-reference is not an approved fitment.": "Uma referência OEM ou de filtro permite buscar equivalências candidatas no Part Search. A compatibilidade final exige verificar a identidade do gerador ou motor, dimensões, sistema protegido e evidências documentadas; uma equivalência não verificada não representa aplicação aprovada.",
    "Does replacing the filter prove that a standby generator will start and transfer the load?": "Trocar o filtro comprova que o gerador de reserva partirá e transferirá a carga?",
    "No. Filtration controls specific contamination risks in engine systems. Emergency readiness also requires OEM-directed starting-system, battery, charging, controls, ATS, protection and appropriate load-testing checks performed by qualified personnel.": "Não. A filtração controla riscos específicos de contaminação dos sistemas do motor. A prontidão para emergências também exige verificações da partida, baterias, carregamento, controles, ATS, proteção e testes sob carga conforme o fabricante e por profissionais qualificados.",
    "Disable unintended automatic starting and follow the OEM isolation procedure before servicing. Verify filter and seal, prevent contamination and document leak checks, safe recommissioning and restoration of the specified standby mode.": "Desative a partida automática involuntária e siga o procedimento OEM de isolamento antes da intervenção. Verifique filtro e vedação, evite contaminação e documente vazamentos, comissionamento seguro e retorno ao modo de reserva especificado.",
    "Scope: filtration reduces specified contamination risks but cannot verify generator start, load acceptance or automatic transfer. Battery, controls, ATS, alternator, electrical protection and OEM-approved load tests require separate checks. Coolant filters require a specified compatible circuit and coolant chemistry.": "Escopo: a filtração reduz riscos determinados de contaminação, mas não comprova partida, aceitação de carga nem transferência automática. Baterias, controles, ATS, alternador, proteção elétrica e testes sob carga aprovados pelo OEM exigem verificações independentes. Filtros de arrefecimento exigem circuito compatível e química do fluido especificados.",
    "POWER GENERATION / ASSET READINESS": "GERAÇÃO DE ENERGIA / PRONTIDÃO DOS ATIVOS",
    "FILTRATION FOR": "FILTRAÇÃO PARA",
    "POWER GENERATION EQUIPMENT": "EQUIPAMENTOS DE GERAÇÃO DE ENERGIA",
    "Engineering support for generator owners, facility maintenance managers, reliability engineers and service technicians.": "Engenharia de filtração para proprietários de geradores, gestores de manutenção, engenheiros de confiabilidade e técnicos de serviço.",
    "Keep standby and prime-power diesel engines prepared for demand. Manage stored-fuel water and particles, air-intake restriction, lubricating-oil condition and OEM-specified coolant filtration before the next load event.": "Mantenha os motores diesel de grupos geradores de reserva e potência principal preparados para atender à demanda. Controle a água e as partículas do combustível armazenado, a restrição na admissão, a condição do óleo e a filtração do líquido de arrefecimento especificada pelo fabricante.",
    "PLAN GENERATOR MAINTENANCE": "PLANEJAR MANUTENÇÃO DO GERADOR",
    "Scope: filtration does not replace battery, starting system, switchgear, automatic transfer switch or electrical load-testing inspections. Cooling-system filters must be specified for the engine and coolant chemistry.": "Escopo: a filtração não substitui inspeções de baterias, partida, equipamentos de manobra, transferência automática nem testes elétricos sob carga. Os filtros do sistema de arrefecimento devem ser especificados para o motor e para a química do fluido.",
    "Power generation equipment applications": "Aplicações de equipamentos de geração de energia",
    "Industrial generator set for standby and prime power applications": "Grupo gerador industrial para aplicações de reserva e potência principal",
    "SERVICE CHECK": "VERIFICAÇÃO DE MANUTENÇÃO",
    "GENERATOR MAINTENANCE RESPONSIBILITIES": "RESPONSABILIDADES NA MANUTENÇÃO DE GERADORES",
    "Four decisions that keep a generator ready for demand.": "Quatro decisões para manter o gerador preparado para atender à demanda.",
    "A ready generator requires coordinated maintenance, not just a replacement filter. Separate contamination and engine issues from starting, transfer-switch and electrical failures; use the equipment manufacturer's complete readiness procedure.": "Um gerador disponível exige manutenção coordenada, não apenas a troca de um filtro. Diferencie problemas de contaminação e motor de falhas de partida, transferência e sistemas elétricos; siga o procedimento completo do fabricante.",
    "Send generator-set and engine model, standby or prime duty, operating and idle hours, fuel-storage history, current filter references, restriction or fluid observations, test results, maintenance log and next service window.": "Informe o modelo do grupo gerador e motor, regime de reserva ou potência principal, horas de operação e inatividade, histórico de combustível armazenado, referências dos filtros, observações de restrição ou fluidos, resultados dos testes, histórico e próxima janela de manutenção.",
    "Tank breathing, condensation and water in stored diesel fuel": "Respiração do tanque, condensação e água no diesel armazenado",
    "FUEL PARTICULATE": "PARTÍCULAS NO COMBUSTÍVEL",
    "Dirt introduced into diesel tanks, transfer hoses and filling points": "Sujeira introduzida nos tanques de diesel, mangueiras de transferência e pontos de abastecimento",
    "DIESEL FUEL": "COMBUSTÍVEL DIESEL",
    "Scale, corrosion debris and coolant condition where a filtration circuit is specified": "Incrustações, resíduos de corrosão e condição do líquido de arrefecimento quando houver circuito de filtração especificado",
    "Generator owner": "Proprietário do gerador",
    "Define the cost of lost power, critical loads and spare-part coverage. Confirm who can authorize maintenance and what emergency service is available.": "Determine o custo da falta de energia, as cargas críticas e a disponibilidade de peças. Confirme quem autoriza a manutenção e qual atendimento emergencial está disponível.",
    "Facility maintenance manager": "Responsável pela manutenção da instalação",
    "Plan calendar-based inspections, fuel storage and water checks, safe service access, documented test schedules and corrective work before the next power event.": "Planeje inspeções por calendário, verificações do combustível armazenado e da água, acesso seguro, testes documentados e trabalhos corretivos antes da próxima interrupção elétrica.",
    "Reliability engineer": "Engenheiro de confiabilidade",
    "Review stored-fuel condition, engine alerts, measured restriction where instrumented, load-test results and OEM application evidence; separate engine filtration from controls and electrical faults.": "Revise o combustível armazenado, alarmes do motor, restrição medida quando instrumentada, resultados dos testes sob carga e evidências OEM; diferencie a filtração do motor de falhas elétricas e de controle.",
    "Service technician": "Técnico de manutenção",
    "Apply lockout and manufacturer isolation procedures, verify the filter and seal, prevent contamination during replacement and document leak checks and return-to-ready testing.": "Aplique os procedimentos de bloqueio e isolamento do fabricante, verifique filtro e vedação, evite a entrada de contaminação na troca e documente vazamentos e testes de retorno à prontidão.",
    "Inspect water accumulation and drain points in stored-diesel systems; use the specified conventional fuel/water separator configuration, not a turbine substitute.": "Inspecione acúmulo de água e drenagens em sistemas de diesel armazenado; utilize o separador convencional de combustível/água especificado, não um substituto tipo turbina.",
    "Review diesel particulate exposure during transfers and fueling; check engine-specific filtration and restriction requirements.": "Revise a entrada de partículas no diesel durante transferências e abastecimento; verifique os requisitos de filtração e restrição específicos do motor.",
    "Check intake restriction, filter-housing sealing and air paths; follow the engine OEM service criteria.": "Verifique a restrição na admissão, vedações da carcaça e dutos de ar; siga os critérios de manutenção OEM do motor.",
    "Review oil condition, service history and operating hours against the engine manufacturer requirements.": "Revise a condição do óleo, histórico de manutenção e horas de operação conforme os requisitos do fabricante do motor.",
    "Only evaluate a coolant filter when the engine manufacturer specifies a compatible cooling-system filtration circuit; verify coolant chemistry and service requirements.": "Considere um filtro de líquido de arrefecimento somente quando o fabricante do motor especificar um circuito compatível de filtração; verifique a química do fluido e os requisitos de manutenção.",
    "POWER GENERATION / READINESS PROTECTION": "GERAÇÃO DE ENERGIA / PROTEÇÃO DE PRONTIDÃO",
    "Power Generation Filtration": "Filtração para geração de energia",
    "Systems": "Sistemas",
    "Protect the generator before the facility has to depend on it.": "Proteja o gerador antes que a instalação precise depender dele.",
    "Fuel, air, lubrication and cooling-system contamination control for standby generators, prime-power systems and industrial engine-driven generation equipment operating across stored readiness, testing and sustained load.": "Controle de contaminação do combustível, ar, lubrificação e arrefecimento para geradores de reserva, geração principal e equipamentos industriais desde a prontidão e testes até a carga sustentada.",
    "IDENTIFY MY GENERATOR PROTECTION PATH": "IDENTIFICAR A PROTEÇÃO DO MEU GERADOR",
    "FIND MY FILTER": "ENCONTRAR MEU FILTRO",
    "DIRECT ANSWER": "RESPOSTA DIRETA",
    "What defines the correct power-generation filtration strategy?": "O que define a estratégia correta de filtração para geração de energia?",
    "Power-generation filtration starts with the generator set and its readiness requirement, then resolves stored-fuel condition, protected system, standby or prime-power duty, environmental exposure, maintenance access and validated application evidence. A filter should not be selected from running hours or generator category alone.": "A seleção começa pelo grupo gerador e seus requisitos de prontidão; depois considera combustível armazenado, sistema protegido, serviço de emergência ou principal, ambiente, manutenção e evidências validadas. Não bastam as horas de uso ou a categoria do gerador.",
    "READINESS BEFORE RUNTIME": "PRONTIDÃO ANTES DA OPERAÇÃO",
    "A standby generator can develop risk while it is not running.": "Um gerador de reserva pode acumular riscos mesmo desligado.",
    "Power-generation protection is unusual because the critical event may happen after long periods of low utilization. Stored fluids, environmental exposure and maintenance condition continue to matter while the hour meter barely moves.": "A proteção é especial porque o evento crítico pode ocorrer após longos períodos de pouca utilização. Fluidos armazenados, ambiente e manutenção importam mesmo quando o horímetro quase não avança.",
    "Different power roles. Different readiness demands.": "Funções elétricas distintas. Exigências de prontidão diferentes.",
    "A hospital standby set, a remote prime-power unit and an industrial emergency generator may share similar engines while operating under very different fuel-storage, testing, loading and maintenance conditions.": "Um gerador hospitalar de reserva, uma unidade principal remota e um grupo de emergência industrial podem ter motores semelhantes, mas diferir em armazenamento de combustível, testes, carga e manutenção.",
    "READINESS PATHWAYS": "ROTAS DE PRONTIDÃO",
    "Connect the failure source to the system that must respond on demand.": "Relacione a fonte de falha ao sistema que deve responder quando solicitado.",
    "Selection should move from contamination source to protected system, then to the appropriate ELIMFILTERS technology and finally to a validated part.": "A seleção deve partir da fonte de contaminação, passar pelo sistema protegido e pela tecnologia ELIMFILTERS e terminar com uma peça validada.",
    "CONTAMINATION SOURCE": "FONTE DE CONTAMINAÇÃO",
    "PROTECTION SYSTEM": "SISTEMA DE PROTEÇÃO",
    "ELIMFILTERS TECHNOLOGY": "TECNOLOGIA ELIMFILTERS",
    "EXPLORE →": "EXPLORAR →",
    "POWER GENERATION ENGINEERING PRINCIPLE": "PRINCÍPIO DE ENGENHARIA DE GERAÇÃO",
    "A generator filter decision must resolve readiness duty, stored-fluid condition, protected system, environmental exposure and application evidence before the product number is accepted.": "A escolha dos filtros deve confirmar regime de prontidão, condição de fluidos armazenados, sistema protegido, ambiente e evidências de aplicação antes de aceitar uma referência.",
    "POWER AVAILABILITY": "DISPONIBILIDADE DE ENERGIA",
    "The filtration consequence is measured when the generator is called.": "A consequência da filtração é medida quando o gerador é solicitado.",
    "For standby and emergency systems, the relevant question is not only whether the engine can run. It is whether the complete generating asset is ready to start, stabilize and carry the required duty when the site loses normal power.": "Em sistemas de reserva e emergência não basta o motor funcionar. Todo o conjunto deve conseguir partir, estabilizar e assumir a carga necessária quando a rede falha.",
    "FROM READINESS CONDITION TO PART": "DA PRONTIDÃO À PEÇA",
    "Resolve the generator application in five decisions.": "Defina a aplicação do gerador em cinco decisões.",
    "APPLICATION EVIDENCE": "EVIDÊNCIA DE APLICAÇÃO",
    "A generator cross-reference still has to match the actual set and duty.": "Uma equivalência deve corresponder ao grupo gerador e seu serviço real.",
    "Final identification should reconcile the known reference, generator-set or engine context, dimensions, protected system and operating responsibility. Where evidence is incomplete, the application should remain under review rather than be treated as confirmed.": "A identificação final deve conciliar referência, grupo ou motor, dimensões, sistema protegido e função operacional. Se faltarem evidências, a aplicação permanece em análise.",
    "POWER GENERATION FILTRATION QUESTIONS": "PERGUNTAS SOBRE FILTRAÇÃO PARA GERAÇÃO DE ENERGIA",
    "What facility, reliability and maintenance teams need to know.": "O que equipes de instalações, confiabilidade e manutenção precisam saber.",
    "HAVE A GENERATOR OR READINESS PROBLEM?": "TEM UM PROBLEMA DE GERADOR OU PRONTIDÃO?",
    "Identify the protection path before the next outage tests the asset.": "Determine a proteção antes que a próxima falta de energia teste o equipamento.",
    "Send the generator set or engine, protected system, standby or prime-power duty, fuel-storage conditions and any known OEM or filter reference.": "Informe gerador ou motor, sistema protegido, tipo de serviço, armazenamento de combustível e referências OEM ou de filtro conhecidas.",
    "ALREADY HAVE A PART NUMBER?": "JÁ TEM UM NÚMERO DE PEÇA?",
    "Go directly to Part Search.": "Acesse diretamente a busca de filtros.",
    "SERVE POWER-GENERATION CUSTOMERS?": "ATENDE CLIENTES DE GERAÇÃO DE ENERGIA?",
    "Evaluate distributor fit.": "Avalie seu perfil de distribuidor.",
    "BECOME A DISTRIBUTOR": "SEJA UM DISTRIBUIDOR",
    "Standby Generator Sets": "Grupos geradores de reserva",
    "Prime Power Systems": "Sistemas de geração principal",
    "Emergency Power Systems": "Sistemas de energia de emergência",
    "Industrial Diesel Generators": "Geradores a diesel industriais",
    "Remote Power Units": "Unidades de energia remotas",
    "Engine-Driven Generation Equipment": "Equipamentos de geração acionados por motor",
    "Stored Fuel": "Combustível armazenado",
    "Start Readiness": "Prontidão para partida",
    "Thermal Control": "Controle térmico",
    "Duty Transition": "Transição de serviço",
    "Standby assets may sit for long periods while fuel is exposed to storage time, tank breathing, condensation and transfer contamination.": "Equipamentos de reserva podem ficar longos períodos parados enquanto o combustível fica exposto a armazenamento, respiro dos tanques, condensação e transferência.",
    "A generator can spend most of its life waiting, then be required to accept load immediately when utility power is unavailable.": "Um gerador pode permanecer inativo grande parte da vida e precisar assumir carga imediatamente quando a rede pública falha.",
    "Cooling-system condition becomes critical once the engine moves from standby to sustained load and heat rejection increases rapidly.": "A condição do sistema de arrefecimento é crítica quando o motor passa de reserva para carga sustentada e aumenta rapidamente o calor a dissipar.",
    "Prime-power and emergency sets can move between low utilization, testing and extended operation, changing filtration demand across the same asset.": "Grupos principais e de emergência podem alternar entre uso baixo, testes e operação prolongada, alterando as exigências de filtração.",
    "FUEL + WATER": "COMBUSTÍVEL E ÁGUA",
    "Stored fuel + tank breathing + condensation + transfer": "Combustível armazenado, respiro dos tanques, condensação e transferência",
    "FUEL / WATER SEPARATION": "SEPARAÇÃO DE COMBUSTÍVEL E ÁGUA",
    "AIRBORNE PARTICULATE": "PARTÍCULAS SUSPENSAS",
    "Ambient dust + enclosure ingress + engine air demand": "Poeira ambiental, entrada na carcaça e demanda de ar do motor",
    "AIR INTAKE": "ADMISSÃO DE AR",
    "LUBE CONTAMINATION": "CONTAMINAÇÃO DO LUBRIFICANTE",
    "Wear debris + soot + oxidation byproducts + service ingress": "Resíduos de desgaste, fuligem, oxidação e entrada na manutenção",
    "LUBRICATION": "LUBRIFICAÇÃO",
    "COOLANT CONTAMINATION": "CONTAMINAÇÃO DO FLUIDO DE ARREFECIMENTO",
    "Scale + corrosion debris + fluid degradation + service contamination": "Incrustações, corrosão, degradação do fluido e contaminação na manutenção",
    "COOLING SYSTEM": "SISTEMA DE ARREFECIMENTO",
    "Starting Reliability": "Confiabilidade da partida",
    "Fuel, air and lubrication condition influence whether the engine can transition from standby to stable operation when demanded.": "A condição de combustível, ar e lubrificação influencia a transição do motor da reserva para operação estável quando necessário.",
    "Load Acceptance": "Aceitação de carga",
    "A generator must move from start-up into electrical load without contamination-related restrictions compromising protected engine systems.": "O gerador deve passar da partida à carga elétrica sem restrições por contaminação que comprometam sistemas protegidos.",
    "Fuel-System Integrity": "Integridade do sistema de combustível",
    "Stored-fuel contamination can reach pumps and injectors before an emergency event exposes the weakness.": "Contaminantes do combustível armazenado podem alcançar bombas e injetores antes que uma emergência revele o problema.",
    "Thermal Stability": "Estabilidade térmica",
    "Cooling-system cleanliness supports controlled heat rejection during sustained generator load.": "A limpeza do sistema de arrefecimento favorece dissipação de calor controlada durante carga sustentada.",
    "Maintenance Readiness": "Prontidão de manutenção",
    "Inspection and service decisions should be completed before an outage turns maintenance access into an operating constraint.": "Inspeções e manutenção devem ser concluídas antes que uma interrupção torne o acesso ao serviço uma limitação operacional.",
    "Power Availability": "Disponibilidade de energia",
    "The filtration strategy supports the larger requirement: keeping the generating asset ready to deliver power when the facility depends on it.": "A estratégia de filtração atende à necessidade de manter o gerador preparado para fornecer energia quando a instalação precisar.",
    "Generator / Engine": "Gerador / Motor",
    "Readiness Duty": "Regime de prontidão",
    "Stored Condition": "Condição de armazenamento",
    "Protection": "Proteção",
    "Application Evidence": "Evidência de aplicação",
    "Identify the generator set, engine family and protected subsystem.": "Identifique grupo gerador, família do motor e subsistema protegido.",
    "Define standby, emergency, prime-power or continuous operating responsibility.": "Defina serviço de reserva, emergência, geração principal ou operação contínua.",
    "Assess fuel storage, fluid age, environment, testing frequency and contamination exposure.": "Avalie armazenamento de combustível, idade dos fluidos, ambiente, frequência de testes e exposição à contaminação.",
    "Match the contamination mechanism to fuel, air intake, lubrication or cooling-system protection.": "Relacione a contaminação à proteção de combustível, admissão, lubrificação ou arrefecimento.",
    "Validate the final filter using OEM reference, dimensions and documented application evidence.": "Valide o filtro com referência OEM, dimensões e evidências documentadas de aplicação.",
    "What filtration systems are most important on generator sets?": "Quais sistemas de filtração são mais importantes nos grupos geradores?",
    "Fuel and water separation, air intake, lubrication and cooling-system protection are common priorities on diesel generator sets. The correct priority depends on whether the unit is standby or prime power, fuel-storage conditions, environment, engine configuration, duty profile and maintenance access.": "Separação de água do combustível, admissão de ar, lubrificação e arrefecimento são prioridades em grupos a diesel. A importância relativa depende de serem de reserva ou principais, armazenamento de combustível, ambiente, motor, regime de trabalho e acesso à manutenção.",
    "Why is standby generator filtration different from continuously operated equipment?": "Por que a filtração de geradores de reserva difere da de equipamentos contínuos?",
    "A standby generator can remain idle for long periods while fuel, fluids, seals and environmental exposure continue to change. When called, the asset may have to start and accept load immediately. Filtration and maintenance planning should therefore account for stored-fluid condition and readiness, not only running hours.": "O gerador de reserva pode ficar desligado muito tempo enquanto combustível, fluidos, vedações e exposição ambiental mudam. Quando necessário, deve partir e assumir carga imediatamente. Por isso, devem ser considerados os fluidos armazenados e a prontidão, não apenas as horas de uso.",
    "How can stored generator fuel become contaminated?": "Como o combustível armazenado para geradores pode ser contaminado?",
    "Fuel can acquire particulate or water through bulk storage, tank breathing, condensation, transfer equipment, maintenance activity and extended storage. The protection strategy should consider the complete fuel path before fuel reaches sensitive pumps and injectors.": "O combustível pode incorporar partículas e água durante armazenamento a granel, respiro de tanques, condensação, transferência, manutenção e permanência prolongada. A proteção deve cobrir toda a rota até bombas e injetores sensíveis.",
    "Why does cooling-system protection matter in power generation?": "Por que a proteção do arrefecimento importa na geração de energia?",
    "Generator engines can move rapidly from standby to sustained thermal load. Cooling-system contamination, scale, corrosion debris or degraded fluid condition can interfere with heat transfer and system stability, so coolant protection should be treated as part of asset readiness.": "Os motores podem passar rapidamente da reserva à carga térmica sustentada. Contaminantes, incrustações, corrosão ou fluido degradado podem afetar a transferência de calor e a estabilidade; proteger o sistema faz parte da prontidão do ativo.",
    "Should generator filters be selected only by operating hours?": "Os filtros de gerador devem ser escolhidos apenas pelas horas de operação?",
    "No. Running hours do not capture stored-fuel condition, calendar aging, environmental dust, fluid degradation, standby duration, testing frequency or the consequences of an emergency start. Selection and service planning should reflect the actual duty profile.": "Não. As horas não refletem qualidade do combustível armazenado, envelhecimento, poeira, degradação dos fluidos, tempo em reserva, frequência de testes ou consequências da partida de emergência. A escolha deve refletir o serviço real.",
    "What information is needed to identify the correct generator filter?": "Quais dados são necessários para identificar o filtro correto do gerador?",
    "Use the generator-set or engine model, protected system, standby or prime-power duty, fuel-storage conditions, environment, OEM or existing part reference, dimensions when available and validated application evidence.": "Use modelo do grupo ou motor, sistema protegido, regime de reserva ou principal, armazenamento de combustível, ambiente, referência OEM ou peça atual, dimensões e evidências validadas.",
    "Can ELIMFILTERS identify a generator filter from an OEM or part number?": "A ELIMFILTERS pode identificar um filtro de gerador por referência OEM?",
    "Yes. If an OEM reference or current filter number is known, Part Search provides the fastest route to cross-reference and application information. For an engineering review, include the generator set, engine, protected system and operating duty.": "Sim. Com referência OEM ou número de filtro, o Part Search permite consultar equivalências e aplicações. Para análise de engenharia, inclua grupo gerador, motor, sistema protegido e regime operacional."
  }
};
export const powerGenerationText = (lang:PageLang, value:string) => lang === 'en' ? value : (translations[lang][value] ?? value);
